struct Query { int u, v, r; std::uint64_t k; };
template<int Api> [[gnu::noinline]] static std::uint64_t run(const LCA& tree,const std::vector<Query>& queries) {
    std::uint64_t result=0;
    for(const auto& q:queries) {
        int answer=0;
        if constexpr(Api==0)answer=tree.parent(q.u);
        if constexpr(Api==1)answer=tree.is_ancestor(q.u,q.v);
        if constexpr(Api==2)answer=tree.kth_ancestor(q.u,q.k);
        if constexpr(Api==3)answer=tree.get_distance(q.u,q.v);
        if constexpr(Api==4)answer=tree.get(q.u,q.v,q.r);
        if constexpr(Api==5)answer=tree.kth_on_path(q.u,q.v,q.k%8);
        result+=static_cast<unsigned>(answer);
    }
    return result;
}
