    std::atomic_signal_fence(std::memory_order_seq_cst);auto begin=std::chrono::steady_clock::now();auto checksum=run<Api>(tree,queries);std::atomic_signal_fence(std::memory_order_seq_cst);auto end=std::chrono::steady_clock::now();
    const auto elapsed=std::chrono::duration_cast<std::chrono::nanoseconds>(end-begin).count();
    std::printf("%s:%s %.6f %llu\n",shape,api,static_cast<double>(elapsed)/queries.size(),static_cast<unsigned long long>(checksum));
}
